import type { ReactNode } from 'react';
import { useEffect, useMemo, useState } from 'react';
import { Link, Navigate, NavLink, Route, Routes, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { Card } from './components/Card';
import { api } from './lib/api';
import type { AgentTask, BuildPlanStep, BuildRun, Business, DiscoveryInput, DiscoveryResponse, EvidenceItem, Opportunity, ResearchEvent, ResearchMode, ResearchResponse, RuntimeEvent, Source } from './lib/types';

const defaultQuery = "McDonald's";
const workspaceTabs = ['research', 'findings', 'plan', 'build', 'live'] as const;
type WorkspaceTab = (typeof workspaceTabs)[number];
const recentBusinessKey = 'businessforge:recent-businesses';

type SearchDraft = { query: string; websiteUrl: string; locationText: string; mode: ResearchMode; coordinates?: DiscoveryInput['coordinates'] };

export default function App() {
  return <main className="min-h-screen bg-[#f5f6f2] text-slate-900"><div className="min-h-screen border-x border-slate-200/70 bg-[#fcfcfa] shadow-[0_0_0_1px_rgba(15,23,42,0.02)] sm:mx-4 sm:my-4 sm:rounded-[28px] lg:mx-6"><AppFrame><Routes><Route path="/" element={<HomePage />} /><Route path="/businesses" element={<BusinessesPage />} /><Route path="/work" element={<WorkPage />} /><Route path="/settings" element={<SettingsPage />} /><Route path="/workspace/:businessId" element={<WorkspacePage />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes></AppFrame></div></main>;
}

function AppFrame({ children }: { children: ReactNode }) {
  return <div><header className="border-b border-slate-200/80 bg-[#fcfcfa]/95 backdrop-blur"><div className="mx-auto flex max-w-7xl items-center justify-between gap-6 px-5 py-4 sm:px-6 lg:px-8"><div className="flex items-center gap-8"><Link to="/" className="flex items-center gap-3 text-sm font-semibold text-slate-950"><span className="flex h-9 w-9 items-center justify-center rounded-2xl border border-slate-300 bg-white text-[13px]">BF</span><span>BusinessForge</span></Link><nav className="hidden items-center gap-1 sm:flex"><TopNavLink to="/">Home</TopNavLink><TopNavLink to="/businesses">Businesses</TopNavLink><TopNavLink to="/work">Work</TopNavLink><TopNavLink to="/settings">Settings</TopNavLink></nav></div><div className="text-right"><p className="text-xs uppercase tracking-[0.18em] text-slate-400">Business operations</p><p className="text-sm text-slate-600">Research, planning, launch</p></div></div></header><div className="mx-auto max-w-7xl px-5 py-8 sm:px-6 lg:px-8 lg:py-10">{children}</div></div>;
}

function TopNavLink({ to, children }: { to: string; children: ReactNode }) {
  return <NavLink to={to} className={({ isActive }) => `rounded-full px-3 py-2 text-sm ${isActive ? 'bg-slate-900 text-white' : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900'}`}>{children}</NavLink>;
}

function HomePage() {
  const navigate = useNavigate();
  const recentBusinesses = useRecentBusinesses();
  const [draft, setDraft] = useState<SearchDraft>({ query: defaultQuery, websiteUrl: '', locationText: '', mode: 'BUSINESS' });
  const [geoState, setGeoState] = useState<'idle' | 'locating' | 'ready' | 'error'>('idle');
  const submit = () => navigate(`/businesses?${toDiscoveryParams(draft).toString()}`);
  const useMyLocation = () => {
    if (!navigator.geolocation) return setGeoState('error');
    setGeoState('locating');
    navigator.geolocation.getCurrentPosition((position) => {
      setDraft((current) => ({ ...current, locationText: 'Near me', coordinates: { latitude: position.coords.latitude, longitude: position.coords.longitude } }));
      setGeoState('ready');
    }, () => setGeoState('error'), { enableHighAccuracy: true, timeout: 8000, maximumAge: 120000 });
  };
  return <div className="space-y-8"><section className="grid gap-8 border-b border-slate-200 pb-8 lg:grid-cols-[1.1fr_0.9fr] lg:items-end"><div><p className="text-sm font-medium text-slate-500">Home</p><h1 className="mt-3 max-w-3xl text-4xl font-semibold tracking-tight text-slate-950 sm:text-5xl">Pick the right business, inspect real public evidence, then approve a live local build.</h1><p className="mt-4 max-w-2xl text-base leading-7 text-slate-600">Business mode is location-aware. Corporation mode is company-wide. We only show source data and build activity that was actually retrieved or generated.</p></div><section className="rounded-[24px] border border-slate-200 bg-white p-5 shadow-sm"><div className="space-y-4"><div><p className="mb-2 block text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">Choose research mode first</p><div className="grid gap-3 sm:grid-cols-2">{(['BUSINESS', 'CORPORATION'] as ResearchMode[]).map((mode) => <button key={mode} onClick={() => setDraft((current) => ({ ...current, mode, locationText: mode === 'CORPORATION' ? '' : current.locationText, coordinates: mode === 'CORPORATION' ? undefined : current.coordinates }))} className={`rounded-[22px] border p-4 text-left ${draft.mode === mode ? 'border-slate-900 bg-slate-950 text-white' : 'border-slate-200 bg-white text-slate-800'}`}><p className="text-sm font-semibold">{mode === 'BUSINESS' ? 'BUSINESS' : 'CORPORATION'}</p><p className={`mt-2 text-sm ${draft.mode === mode ? 'text-slate-200' : 'text-slate-500'}`}>{mode === 'BUSINESS' ? 'Search a specific location, address, near me, or category + place.' : 'Search a company or brand with no location required.'}</p></button>)}</div></div><SearchField label={draft.mode === 'BUSINESS' ? 'Business or category' : 'Company or brand'} value={draft.query} onChange={(value) => setDraft((current) => ({ ...current, query: value }))} placeholder={draft.mode === 'BUSINESS' ? 'Blue Bottle Coffee, pizza near me, dentist in Seattle' : "McDonald's, Starbucks, Shake Shack"} /><SearchField label="Website" value={draft.websiteUrl} onChange={(value) => setDraft((current) => ({ ...current, websiteUrl: value }))} placeholder="Optional official website" />{draft.mode === 'BUSINESS' ? <SearchField label="City, area, or address" value={draft.locationText} onChange={(value) => setDraft((current) => ({ ...current, locationText: value, coordinates: value === 'Near me' ? current.coordinates : undefined }))} placeholder="Downtown Seattle, 1st Ave, Austin TX" /> : null}</div><div className="mt-4 flex flex-wrap gap-3"><button onClick={submit} className="rounded-2xl bg-slate-950 px-5 py-3 text-sm font-semibold text-white">Search and analyze</button>{draft.mode === 'BUSINESS' ? <button onClick={useMyLocation} className="rounded-2xl border border-slate-200 bg-white px-5 py-3 text-sm font-semibold text-slate-700">{geoState === 'locating' ? 'Finding location…' : geoState === 'ready' ? 'Using your location' : 'Use my location'}</button> : null}</div><p className="mt-3 text-sm text-slate-500">{geoState === 'error' ? 'Location access was unavailable. You can still search by city or address.' : draft.mode === 'BUSINESS' ? 'Examples: business name + city, business + address, near me, or category + location.' : 'Corporation mode keeps the company-wide scope visible through the workflow.'}</p></section></section><section className="grid gap-8 lg:grid-cols-[1.1fr_0.9fr]"><Card title="Recent businesses" subtitle="Continue from the businesses you reviewed most recently"><BusinessList businesses={recentBusinesses} emptyCopy="No recent businesses yet." /></Card><Card title="How it works" subtitle="A direct demo flow"><ol className="space-y-4 text-sm text-slate-600">{[['Find the exact business', 'Match the right location or switch to corporation scope.'], ['Run research', 'See official pages, search-discovered review/forum/news/directory evidence, and blocked-source limits.'], ['Choose an opportunity', 'Select what is worth building.'], ['Approve the build', 'Start a real asynchronous local build.'], ['Inspect files and preview', 'See the mini-app, files, events, and validation trail.']].map(([title, copy], index) => <li key={title} className="flex gap-4 border-b border-slate-100 pb-4 last:border-b-0 last:pb-0"><span className="mt-0.5 text-sm font-semibold text-slate-400">0{index + 1}</span><div><p className="font-medium text-slate-900">{title}</p><p className="mt-1 leading-6">{copy}</p></div></li>)}</ol></Card></section></div>;
}

function BusinessesPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const recentBusinesses = useRecentBusinesses();
  const [matches, setMatches] = useState<Business[]>([]);
  const [selected, setSelected] = useState<Business | null>(null);
  const [suggestion, setSuggestion] = useState<string | null>(null);
  const [run, setRun] = useState<ResearchResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const input = useMemo<DiscoveryInput>(() => ({ query: searchParams.get('q') ?? '', websiteUrl: searchParams.get('website') ?? undefined, locationText: searchParams.get('location') === 'Near me' ? undefined : searchParams.get('location') ?? undefined, mode: (searchParams.get('mode') as ResearchMode) || 'BUSINESS', coordinates: searchParams.get('lat') && searchParams.get('lng') ? { latitude: Number(searchParams.get('lat')), longitude: Number(searchParams.get('lng')) } : undefined }), [searchParams]);

  useEffect(() => {
    if (!input.query.trim()) return;
    let cancelled = false;
    setLoading(true);
    api.discover(input).then((res: DiscoveryResponse) => {
      if (cancelled) return;
      setMatches(res.matches); setSelected(res.matches[0] ?? null); setSuggestion(res.suggestion); setError(null);
    }).catch((err: Error) => !cancelled && setError(toPlainError(err.message, 'We could not look up that business right now.'))).finally(() => !cancelled && setLoading(false));
    return () => { cancelled = true; };
  }, [input]);

  useEffect(() => {
    if (!run || run.run.status === 'complete') return;
    const timer = setInterval(async () => {
      const next = await api.getResearch(run.run.id);
      setRun(next);
      if (next.run.status === 'complete') { rememberBusiness(next.business.id); navigate(`/workspace/${next.business.id}?tab=research`); }
    }, 900);
    return () => clearInterval(timer);
  }, [navigate, run]);

  const startResearch = async () => { if (!selected) return; rememberBusiness(selected.id); setRun(await api.startResearch(selected.id)); };
  const hasSearch = Boolean(input.query.trim());

  return <div className="space-y-8"><section className="flex flex-col gap-4 border-b border-slate-200 pb-6 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-sm font-medium text-slate-500">Businesses</p><h1 className="mt-2 text-3xl font-semibold tracking-tight text-slate-950">{hasSearch ? 'Choose the exact match' : 'Your businesses'}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{hasSearch ? 'Business mode is location-aware, corporation mode is company-wide. Choose the right match before research starts.' : 'Recent workspaces appear here.'}</p></div><ModeBanner mode={input.mode ?? 'BUSINESS'} /><Link to="/" className="rounded-2xl border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700">Analyze another business</Link></section>{!hasSearch ? <Card title="Recent businesses" subtitle="Saved from your recent work"><BusinessList businesses={recentBusinesses} emptyCopy="No businesses yet." /></Card> : <div className="grid gap-8 xl:grid-cols-[1.08fr_0.92fr]"><Card title="Matches" subtitle="Public place or corporation matches with only actually returned fields">{suggestion ? <InlineNote>{suggestion}</InlineNote> : null}{error ? <ErrorMessage message={error} /> : null}{loading ? <LoadingPanel label="Finding matching businesses" /> : <BusinessChooser matches={matches} selected={selected} onSelect={setSelected} />}</Card><Card title={selected?.name ?? 'Selected business'} subtitle={selected ? 'Review the identity before starting research.' : 'Choose a match first.'}>{selected ? <div className="space-y-5"><BusinessSnapshot business={selected} />{run ? <ResearchRunPanel run={run} /> : null}<button onClick={startResearch} disabled={Boolean(run && run.run.status !== 'complete')} className="w-full rounded-2xl bg-slate-950 px-5 py-3 text-sm font-semibold text-white disabled:opacity-50">{run && run.run.status !== 'complete' ? 'Investigating…' : 'Start investigation'}</button></div> : <EmptyState copy="Select a business from the list to continue." />}</Card></div>}</div>;
}

function WorkPage() { const recentBusinesses = useRecentBusinesses(); const researched = recentBusinesses.filter((business) => business.stage === 'researched'); return <div className="space-y-8"><section className="border-b border-slate-200 pb-6"><p className="text-sm font-medium text-slate-500">Work</p><h1 className="mt-2 text-3xl font-semibold tracking-tight text-slate-950">Active work</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">Businesses with findings or builds already in motion.</p></section><Card title="Workspaces" subtitle="Businesses that already have working plans or live build activity"><BusinessList businesses={researched} emptyCopy="No active workspaces yet." showStage /></Card></div>; }
function SettingsPage() { return <Card title="Settings" subtitle="Demo placeholder"><p className="text-sm text-slate-600">Settings are not configurable in this demo yet.</p></Card>; }

function WorkspacePage() {
  const { businessId = '' } = useParams();
  const [searchParams, setSearchParams] = useSearchParams();
  const [business, setBusiness] = useState<Business | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState('Please keep moving and flag anything that still needs a decision from me.');
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [selectedFileContent, setSelectedFileContent] = useState<string>('');
  const activeTab = ((searchParams.get('tab') as WorkspaceTab) || 'research');
  const selectedOpportunity = business?.opportunities?.find((opp) => opp.id === business.selectedOpportunityId);
  const evidenceById = useMemo(() => new Map((business?.evidenceItems ?? []).map((item) => [item.id, item])), [business?.evidenceItems]);
  const sourcesById = useMemo(() => new Map((business?.sources ?? []).map((item) => [item.id, item])), [business?.sources]);
  const groupedSources = useMemo(() => groupSources(business?.sources ?? []), [business?.sources]);
  const latestBuild = business?.runtime?.buildRuns?.[0];

  useEffect(() => { let cancelled = false; setLoading(true); api.getBusiness(businessId).then((next) => { if (cancelled) return; setBusiness(next); rememberBusiness(next.id); setError(null); }).catch((err: Error) => !cancelled && setError(toPlainError(err.message, 'We could not load this workspace right now.'))).finally(() => !cancelled && setLoading(false)); return () => { cancelled = true; }; }, [businessId]);

  useEffect(() => {
    if (!business?.runtime?.buildRuns?.length) return;
    const running = business.runtime.buildRuns.some((run) => run.status === 'pending' || run.status === 'running');
    if (!running) return;
    const timer = setInterval(async () => { const next = await api.getBusiness(businessId); setBusiness(next); rememberBusiness(next.id); }, 900);
    return () => clearInterval(timer);
  }, [business?.runtime?.buildRuns, businessId]);

  useEffect(() => {
    if (!selectedFile || !business) return;
    api.readBuildFile(business.id, selectedFile).then((res) => setSelectedFileContent(res.content)).catch(() => setSelectedFileContent('Could not read file.'));
  }, [selectedFile, business]);

  const chooseOpportunity = async (opportunityId: string) => { if (!business) return; const next = await api.selectOpportunity(business.id, opportunityId); setBusiness(next); rememberBusiness(next.id); setSearchParams({ tab: 'build' }); };
  const startBuild = async () => { if (!business) return; const next = await api.startBuild(business.id); setBusiness(next); rememberBusiness(next.id); setSearchParams({ tab: 'build' }); };
  const updateTask = async (taskId: string, action: 'advance' | 'block') => { if (!business) return; const next = await api.updateTask(business.id, taskId, action); setBusiness(next); rememberBusiness(next.id); };
  const sendMessage = async () => { if (!business?.runtime?.agents.length || !message.trim()) return; const res = await api.interact(business.id, business.runtime.agents[0].id, message); setBusiness(res.business); rememberBusiness(res.business.id); setMessage(''); };

  if (loading) return <LoadingPanel label="Loading business workspace" />;
  if (error || !business) return <ErrorMessage message={error ?? 'Business workspace not found.'} />;

  return <div className="space-y-8"><section className="border-b border-slate-200 pb-6"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><Link to="/businesses" className="text-sm font-medium text-slate-600">← Back to businesses</Link><h1 className="mt-3 text-3xl font-semibold tracking-tight text-slate-950">{business.name}</h1><div className="mt-3 flex flex-wrap items-center gap-3 text-sm text-slate-600"><ModeBanner mode={business.mode} compact />{business.city ? <span>{business.city}</span> : null}{business.address ? <span>• {business.address}</span> : null}{business.websiteUrl ? <a href={business.websiteUrl} target="_blank" rel="noreferrer" className="text-sky-700 hover:text-sky-800">{business.websiteUrl}</a> : null}</div></div><div className="flex flex-wrap gap-2"><StatusPill tone="green">{business.stage === 'researched' ? 'Workspace ready' : 'Business found'}</StatusPill><StatusPill tone="slate">{business.sources.length} sources</StatusPill>{business.researchEvents ? <StatusPill tone="slate">{business.researchEvents.length} research events</StatusPill> : null}{latestBuild ? <StatusPill tone="orange">{latestBuild.status}</StatusPill> : null}</div></div><div className="mt-6 flex flex-wrap gap-2">{workspaceTabs.map((tab) => <button key={tab} onClick={() => setSearchParams({ tab })} className={`rounded-full px-4 py-2 text-sm font-semibold capitalize ${activeTab === tab ? 'bg-slate-950 text-white' : 'border border-slate-200 bg-white text-slate-600 hover:border-slate-300'}`}>{tab}</button>)}</div></section>{activeTab === 'research' ? <ResearchTab business={business} groupedSources={groupedSources} /> : null}{activeTab === 'findings' ? <FindingsTab business={business} evidenceById={evidenceById} sourcesById={sourcesById} /> : null}{activeTab === 'plan' ? <PlanTab business={business} selectedOpportunity={selectedOpportunity} evidenceById={evidenceById} sourcesById={sourcesById} onSelectOpportunity={chooseOpportunity} /> : null}{activeTab === 'build' ? <BuildTab business={business} selectedOpportunity={selectedOpportunity} message={message} onMessageChange={setMessage} onSendMessage={sendMessage} onUpdateTask={updateTask} onStartBuild={startBuild} selectedFile={selectedFile} onSelectFile={setSelectedFile} selectedFileContent={selectedFileContent} /> : null}{activeTab === 'live' ? <LiveTab business={business} /> : null}</div>;
}

function ResearchTab({ business, groupedSources }: { business: Business; groupedSources: ReturnType<typeof groupSources> }) {
  return <div className="grid gap-8 xl:grid-cols-[0.95fr_1.05fr]"><Card title="Research activity" subtitle="Real event log and retrieved-source counts"><div className="grid gap-4 sm:grid-cols-3"><MiniStat label="Research events" value={business.researchEvents?.length ?? 0} /><MiniStat label="Retrieved sources" value={business.sources.length} /><MiniStat label="Blocked/snippet only" value={business.sources.filter((source) => source.contentAvailability === 'blocked' || source.availability === 'snippet-only').length} /></div><div className="mt-5 space-y-3">{(business.researchEvents ?? []).map((event) => <ResearchEventRow key={event.id} event={event} />)}{!business.researchEvents?.length ? <EmptyState copy="Run research to see the event trail." /> : null}</div>{business.researchMetadata?.limitations?.length ? <div className="mt-5 rounded-[20px] border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800"><p className="font-semibold">Honest limitations</p><ul className="mt-2 space-y-1">{business.researchMetadata.limitations.map((item) => <li key={item}>• {item}</li>)}</ul></div> : null}</Card><Card title="Sources" subtitle="Official pages, reviews, forums, news, directories, and snippet-only discoveries"><div className="space-y-5">{groupedSources.map((group) => <section key={group.key} className="border-b border-slate-100 pb-5 last:border-b-0 last:pb-0"><div className="flex items-start justify-between gap-3"><div><h3 className="font-medium text-slate-900">{group.label}</h3><p className="mt-1 text-sm text-slate-500">{group.summary}</p></div><StatusPill tone="slate">{group.items.length}</StatusPill></div><div className="mt-3 space-y-3">{group.items.map((source) => <SourceListItem key={source.id} source={source} />)}</div></section>)}</div></Card></div>;
}

function FindingsTab({ business, evidenceById, sourcesById }: { business: Business; evidenceById: Map<string, EvidenceItem>; sourcesById: Map<string, Source> }) {
  const report = business.report; if (!report) return <EmptyState copy="Findings will appear here after the investigation runs." />;
  return <div className="space-y-8"><Card title="What we found" subtitle="Summary grounded in retrieved evidence"><div className="grid gap-8 xl:grid-cols-[1.05fr_0.95fr]"><p className="text-base leading-7 text-slate-700">{report.summary}</p><div className="grid gap-4 sm:grid-cols-3"><MiniStat label="Sources" value={business.sources.length} /><MiniStat label="Themes" value={report.keyThemes.length} /><MiniStat label="Opportunities" value={business.opportunities?.length ?? 0} /></div></div></Card><div className="grid gap-8 xl:grid-cols-3"><SummaryList title="Strong signals" items={report.strengths} emptyCopy="No strengths captured yet." /><SummaryList title="Needs attention" items={report.gaps} emptyCopy="No gaps captured yet." /><SummaryList title="Why it matters" items={report.marketSignals} emptyCopy="No business implications captured yet." /></div><Card title="Evidence-backed findings" subtitle="Each finding links back to retrieved excerpts and sources">{(business.evidenceItems ?? []).map((item) => <section key={item.id} className="border-b border-slate-100 pb-5 last:border-b-0 last:pb-0"><div className="flex flex-wrap items-center gap-2"><StatusPill tone={findingTone(item.sentiment)}>{humanizeFindingType(item.type)}</StatusPill><span className="text-sm text-slate-400">{item.evidenceCount} excerpts</span><span className="text-sm text-slate-400">score {item.confidence}</span></div><h3 className="mt-3 text-lg font-semibold text-slate-950">{item.statement}</h3><p className="mt-2 text-sm leading-6 text-slate-600">Why it matters: {item.implication}</p><div className="mt-3 space-y-2 text-sm text-slate-500">{item.supportingExcerpts.slice(0, 3).map((entry, index) => <p key={`${entry.sourceId}-${index}`}>“{entry.text}”</p>)}</div><div className="mt-3 flex flex-wrap gap-2">{item.sourceIds.map((id) => sourcesById.get(id)).filter(Boolean).map((source) => <a key={source?.id} href={source?.url} target="_blank" rel="noreferrer" className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-600">{source?.title}</a>)}</div></section>)}<details className="mt-6 rounded-[22px] border border-slate-200 bg-slate-50 px-4 py-3"><summary className="cursor-pointer list-none text-sm font-medium text-slate-700">Evidence assembly details</summary><div className="mt-3 space-y-3 text-sm text-slate-600">{report.evidence.map((claim, index) => <div key={`${claim.claim}-${index}`} className="border-b border-slate-200 pb-3 last:border-b-0 last:pb-0"><p className="font-medium text-slate-900">{claim.claim}</p><p className="mt-1">Supported by {claim.sourceIds.length} source{claim.sourceIds.length === 1 ? '' : 's'} and {claim.evidenceIds.map((id) => evidenceById.get(id)?.theme).filter(Boolean).join(', ')}.</p></div>)}</div></details></Card></div>;
}

function PlanTab({ business, selectedOpportunity, evidenceById, sourcesById, onSelectOpportunity }: { business: Business; selectedOpportunity?: Opportunity; evidenceById: Map<string, EvidenceItem>; sourcesById: Map<string, Source>; onSelectOpportunity: (opportunityId: string) => void }) {
  const opportunities = business.opportunities ?? [];
  return <div className="space-y-8"><Card title="Opportunities" subtitle="Choose the improvement worth building first">{opportunities.length ? <div className="space-y-6">{opportunities.map((opportunity, index) => { const evidenceItems = opportunity.evidenceIds.map((id) => evidenceById.get(id)).filter(Boolean) as EvidenceItem[]; const selected = selectedOpportunity?.id === opportunity.id; return <section key={opportunity.id} className={`rounded-[24px] border px-5 py-5 ${selected ? 'border-slate-900 bg-slate-50' : 'border-slate-200 bg-white'}`}><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div className="max-w-3xl"><div className="flex flex-wrap items-center gap-2"><span className="text-sm font-semibold text-slate-400">0{index + 1}</span>{selected ? <StatusPill tone="green">Selected</StatusPill> : null}</div><h3 className="mt-2 text-xl font-semibold text-slate-950">{opportunity.title}</h3><p className="mt-2 text-sm leading-6 text-slate-600">Problem: {opportunity.rationale}</p><p className="mt-2 text-sm leading-6 text-slate-600">What BusinessForge can build: {describeOpportunityBuild(opportunity, business.category)}</p></div><div className="flex flex-wrap gap-2"><MetricChip label={`Impact ${opportunity.impact}`} /><MetricChip label={`Confidence ${opportunity.confidence}`} /><MetricChip label={`Setup ${humanizeEffort(opportunity.effort)}`} /></div></div><div className="mt-4 grid gap-3 lg:grid-cols-2"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-slate-400">Evidence</p><ul className="mt-2 space-y-2 text-sm text-slate-600">{evidenceItems.slice(0, 3).map((item) => <li key={item.id}>{item.statement}</li>)}</ul></div><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-slate-400">Sources</p><div className="mt-2 flex flex-wrap gap-2">{uniqueSourcesFromEvidence(evidenceItems, sourcesById).map((source) => <a key={source.id} href={source.url} target="_blank" rel="noreferrer" className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-600">{source.title}</a>)}</div></div></div><div className="mt-5 flex flex-wrap gap-3"><button onClick={() => onSelectOpportunity(opportunity.id)} className="rounded-2xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white">Choose this build</button>{selected ? <span className="inline-flex items-center rounded-2xl border border-slate-200 px-4 py-2.5 text-sm text-slate-600">Current plan</span> : null}</div></section>; })}</div> : <EmptyState copy="Opportunities will appear here after the investigation is complete." />}</Card>{selectedOpportunity && business.buildPlan ? <Card title="Here’s what we’ll build" subtitle="Plan generated from the selected opportunity"><div className="grid gap-4 sm:grid-cols-3"><MiniStat label="Selected plan" value={selectedOpportunity.title} /><MiniStat label="Estimated setup" value={humanizeEffort(selectedOpportunity.effort)} /><MiniStat label="Uses evidence" value={`${selectedOpportunity.evidenceIds.length} signals`} /></div><div className="mt-5 space-y-4">{business.buildPlan.map((step, index) => <BuildPlanRow key={step.id} step={step} index={index} />)}</div></Card> : null}</div>;
}

function BuildTab({ business, selectedOpportunity, message, onMessageChange, onSendMessage, onUpdateTask, onStartBuild, selectedFile, onSelectFile, selectedFileContent }: { business: Business; selectedOpportunity?: Opportunity; message: string; onMessageChange: (value: string) => void; onSendMessage: () => void; onUpdateTask: (taskId: string, action: 'advance' | 'block') => void; onStartBuild: () => void; selectedFile: string | null; onSelectFile: (path: string) => void; selectedFileContent: string }) {
  if (!business.runtime || !selectedOpportunity) return <EmptyState copy="Choose a plan first." />;
  const latestBuild = business.runtime.buildRuns[0];
  const buildStarted = Boolean(latestBuild);
  return <div className="space-y-8"><Card title="Build approval" subtitle="Selecting an opportunity does not start the build"><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div><p className="font-medium text-slate-900">{selectedOpportunity.title}</p><p className="mt-1 text-sm text-slate-600">Approve the build to generate a real local mini-app with files, validation, and preview.</p></div><div className="flex flex-wrap gap-3"><button onClick={onStartBuild} disabled={buildStarted && (latestBuild.status === 'pending' || latestBuild.status === 'running')} className="rounded-2xl bg-slate-950 px-5 py-3 text-sm font-semibold text-white disabled:opacity-50">{buildStarted ? 'Build already started' : 'Approve and start build'}</button>{latestBuild?.previewUrl ? <a href={latestBuild.previewUrl} target="_blank" rel="noreferrer" className="rounded-2xl border border-slate-200 bg-white px-5 py-3 text-sm font-semibold text-slate-700">Open preview</a> : null}</div></div></Card><div className="grid gap-6 xl:grid-cols-[240px_1fr_320px]"><Card title="Files" subtitle="Generated workspace">{latestBuild?.files.length ? <div className="space-y-2">{latestBuild.files.map((file) => <button key={file.path} onClick={() => onSelectFile(file.path)} className={`block w-full rounded-xl border px-3 py-2 text-left text-sm ${selectedFile === file.path ? 'border-slate-900 bg-slate-950 text-white' : 'border-slate-200 bg-white text-slate-700'}`}>{file.name}<span className={`block text-xs ${selectedFile === file.path ? 'text-slate-300' : 'text-slate-400'}`}>{file.path}</span></button>)}</div> : <EmptyState copy="Start the build to see files appear." />}</Card><Card title="Editor" subtitle={selectedFile ?? 'Select a generated file'}>{selectedFile ? <pre className="max-h-[640px] overflow-auto rounded-[18px] bg-slate-950 p-4 text-xs text-slate-100">{selectedFileContent}</pre> : <EmptyState copy="Select a file to inspect generated code." />}</Card><div className="space-y-6"><Card title="Build status" subtitle="Workers and validation"><div className="space-y-3"><StatusPill tone="orange">{humanizeRuntimeStatus(business.runtime.status)}</StatusPill>{latestBuild ? <><MiniStat label="Build" value={latestBuild.status} /><MiniStat label="Artifacts" value={latestBuild.artifacts.length} /><MiniStat label="Validations" value={latestBuild.validations.length} /></> : <p className="text-sm text-slate-500">No build run yet.</p>}</div><div className="mt-4 space-y-4">{business.runtime.tasks.map((task, index) => <TaskRow key={task.id} task={task} index={index} onUpdateTask={onUpdateTask} />)}</div></Card><Card title="Instruction" subtitle="Adjust direction without leaving the workspace"><textarea value={message} onChange={(e) => onMessageChange(e.target.value)} className="min-h-28 w-full rounded-[22px] border border-slate-200 bg-white p-4 text-sm text-slate-900 outline-none" /><div className="mt-3 flex justify-end"><button onClick={onSendMessage} className="rounded-2xl bg-slate-950 px-4 py-3 text-sm font-semibold text-white">Send instruction</button></div></Card></div></div><Card title="Activity log" subtitle="Build and runtime events"><div className="space-y-3 max-h-[340px] overflow-auto">{buildStarted ? latestBuild.events.map((event) => <EventLine key={event.id} when={event.at} label={event.type} text={event.text} />) : <EmptyState copy="Build events will appear here after approval." />}{business.runtime.eventLog.slice(0, 8).map((event) => <EventLine key={event.id} when={event.at} label={event.type} text={humanizeEventText(event)} />)}</div></Card></div>;
}

function LiveTab({ business }: { business: Business }) {
  const deployment = business.deployment; const latestBuild = business.runtime?.buildRuns?.[0];
  return <div className="grid gap-8 xl:grid-cols-[0.9fr_1.1fr]"><Card title="Preview and deployment" subtitle="Honest local outcome"><div className="space-y-4"><div className="flex flex-wrap gap-2">{['draft', 'validating', 'deploying', 'live'].map((state) => <StatusPill key={state} tone={deployment?.state === state ? 'orange' : 'slate'}>{humanizeDeploymentState(state)}</StatusPill>)}</div><p className="text-sm text-slate-600">{deployment?.honestStatus}</p>{deployment?.previewUrl ? <a href={deployment.previewUrl} target="_blank" rel="noreferrer" className="text-sm font-medium text-sky-700">Open local preview</a> : null}<div className="space-y-3">{deployment?.history.map((item) => <div key={`${item.at}-${item.state}`} className="border-b border-slate-100 pb-3 last:border-b-0 last:pb-0"><div className="flex items-center justify-between gap-3"><p className="font-medium text-slate-900">{humanizeDeploymentState(item.state)}</p><p className="text-xs text-slate-400">{formatTime(item.at)}</p></div><p className="mt-1 text-sm text-slate-600">{item.note}</p></div>)}</div></div></Card><div className="space-y-8"><Card title="Checks" subtitle="Validation and repair trail"><div className="space-y-3">{(latestBuild?.validations ?? business.runtime?.tests ?? []).map((test) => <div key={test.id} className="rounded-[18px] border border-slate-200 bg-white p-4"><div className="flex items-center justify-between gap-3"><h3 className="font-medium text-slate-900">{test.name}</h3><StatusPill tone={test.status === 'pass' ? 'green' : 'amber'}>{test.status === 'pass' ? 'Passed' : 'Needs review'}</StatusPill></div><p className="mt-2 text-sm text-slate-600">{test.details}</p></div>)}{latestBuild?.repairNotes.length ? <div className="rounded-[18px] border border-slate-200 bg-slate-50 p-4 text-sm text-slate-600">Repair notes: {latestBuild.repairNotes.join(' ')}</div> : null}</div></Card><Card title="Recent activity" subtitle="Runtime and build feed"><div className="space-y-3">{(business.runtime?.eventLog ?? []).slice(0, 14).map((event) => <EventRow key={event.id} event={event} />)}</div></Card></div></div>;
}

function BusinessChooser({ matches, selected, onSelect }: { matches: Business[]; selected: Business | null; onSelect: (business: Business) => void }) { if (!matches.length) return <EmptyState copy="No businesses matched that search." />; return <div className="divide-y divide-slate-100">{matches.map((match) => { const active = selected?.id === match.id; return <button key={match.id} onClick={() => onSelect(match)} className={`flex w-full items-start justify-between gap-4 px-1 py-4 text-left ${active ? 'text-slate-950' : 'text-slate-700 hover:text-slate-950'}`}><div><div className="flex flex-wrap items-center gap-2"><h3 className="text-base font-semibold">{match.name}</h3>{active ? <StatusPill tone="green">Selected</StatusPill> : null}<ModeBanner mode={match.mode} compact /></div><p className="mt-1 text-sm text-slate-500">{match.searchMeta?.locationLabel ?? match.city}</p><div className="mt-2 flex flex-wrap gap-2 text-xs text-slate-500">{match.searchMeta?.distanceMeters ? <span>{formatDistance(match.searchMeta.distanceMeters)}</span> : null}{match.searchMeta?.phone ? <span>{match.searchMeta.phone}</span> : null}{match.searchMeta?.websiteUrl ? <span>{new URL(match.searchMeta.websiteUrl).hostname.replace(/^www\./, '')}</span> : null}{match.searchMeta?.hours?.[0] ? <span>{match.searchMeta.hours[0]}</span> : null}</div><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{match.description}</p></div><div className="pt-1 text-right text-sm text-slate-400">{match.discoveryScore} match</div></button>; })}</div>; }
function BusinessSnapshot({ business }: { business: Business }) { return <div className="space-y-4 rounded-[22px] border border-slate-200 bg-slate-50 p-5"><div className="flex flex-wrap gap-2"><ModeBanner mode={business.mode} compact /><StatusPill tone="slate">{business.category}</StatusPill>{business.searchMeta?.distanceMeters ? <StatusPill tone="slate">{formatDistance(business.searchMeta.distanceMeters)}</StatusPill> : null}{business.phone ? <StatusPill tone="slate">{business.phone}</StatusPill> : null}</div><p className="text-sm leading-6 text-slate-600">{business.description}</p>{business.hours?.length ? <p className="text-sm text-slate-500">Hours: {business.hours.join(' • ')}</p> : null}{business.websiteUrl ? <a href={business.websiteUrl} target="_blank" rel="noreferrer" className="text-sm font-medium text-sky-700">View website</a> : null}</div>; }
function ResearchRunPanel({ run }: { run: ResearchResponse }) { return <div className="rounded-[22px] border border-slate-200 bg-white p-5"><div className="flex items-center justify-between gap-4 text-sm text-slate-600"><span>{humanizeResearchStage(run.currentStage)}</span><span>{run.progress}%</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-slate-900" style={{ width: `${run.progress}%` }} /></div><p className="mt-3 text-sm text-slate-600">We&apos;re logging actual research events and only counting retrieved sources.</p></div>; }
function BusinessList({ businesses, emptyCopy, showStage = false }: { businesses: Business[]; emptyCopy: string; showStage?: boolean }) { if (!businesses.length) return <EmptyState copy={emptyCopy} />; return <div className="divide-y divide-slate-100">{businesses.map((business) => <Link key={business.id} to={`/workspace/${business.id}?tab=${business.stage === 'researched' ? 'findings' : 'research'}`} className="flex items-start justify-between gap-4 px-1 py-4 hover:bg-slate-50"><div><div className="flex flex-wrap items-center gap-2"><h3 className="font-medium text-slate-900">{business.name}</h3>{showStage ? <StatusPill tone={business.stage === 'researched' ? 'green' : 'slate'}>{business.stage === 'researched' ? 'Ready' : 'Found'}</StatusPill> : null}<ModeBanner mode={business.mode} compact /></div><p className="mt-1 text-sm text-slate-500">{business.city}</p><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{business.report?.summary ?? business.description}</p></div><span className="pt-1 text-sm text-slate-400">Open</span></Link>)}</div>; }
function BuildPlanRow({ step, index }: { step: BuildPlanStep; index: number }) { return <div className="flex gap-4 border-b border-slate-100 pb-4 last:border-b-0 last:pb-0"><span className="text-sm font-semibold text-slate-400">0{index + 1}</span><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-medium text-slate-900">{step.title}</p><StatusPill tone={step.status === 'done' ? 'green' : step.status === 'doing' ? 'orange' : 'slate'}>{humanizePlanStatus(step.status)}</StatusPill></div><p className="mt-1 text-sm text-slate-600">{step.outcome}</p><p className="mt-1 text-sm text-slate-500">Led by {step.owner}</p></div></div>; }
function TaskRow({ task, index, onUpdateTask }: { task: AgentTask; index: number; onUpdateTask: (taskId: string, action: 'advance' | 'block') => void }) { return <div className="rounded-[22px] border border-slate-200 bg-white p-4"><div className="flex flex-col gap-3"><div className="flex flex-wrap items-center gap-2"><span className="text-sm font-semibold text-slate-400">0{index + 1}</span><h3 className="font-medium text-slate-900">{humanizeTaskTitle(task.title)}</h3><StatusPill tone={task.status === 'done' ? 'green' : task.status === 'blocked' ? 'amber' : task.status === 'running' ? 'orange' : 'slate'}>{humanizeTaskStatus(task.status)}</StatusPill></div><p className="text-sm leading-6 text-slate-600">{humanizeTaskNotes(task.notes)}</p><div className="flex gap-2"><button onClick={() => onUpdateTask(task.id, 'advance')} className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700">Advance</button><button onClick={() => onUpdateTask(task.id, 'block')} className="rounded-xl border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-700">Needs review</button></div></div></div>; }
function EventRow({ event }: { event: RuntimeEvent }) { return <EventLine when={event.at} label={humanizeEventType(event.type)} text={humanizeEventText(event)} />; }
function ResearchEventRow({ event }: { event: ResearchEvent }) { return <EventLine when={event.at} label={event.type.replace(/_/g, ' ')} text={`${event.text}${event.detail ? ` (${event.detail})` : ''}`} />; }
function EventLine({ when, label, text }: { when: string; label: string; text: string }) { return <div className="border-b border-slate-100 pb-3 last:border-b-0 last:pb-0"><div className="flex items-start justify-between gap-4"><div><p className="text-sm text-slate-700">{text}</p><p className="mt-1 text-xs uppercase tracking-[0.16em] text-slate-400">{label}</p></div><p className="whitespace-nowrap text-xs text-slate-400">{formatTime(when)}</p></div></div>; }
function SummaryList({ title, items, emptyCopy }: { title: string; items: string[]; emptyCopy: string }) { return <Card title={title}>{items.length ? <ul className="space-y-3 text-sm text-slate-600">{items.map((item) => <li key={item} className="leading-6">{item}</li>)}</ul> : <EmptyState copy={emptyCopy} />}</Card>; }
function SourceListItem({ source }: { source: Source }) { return <div className="rounded-[18px] border border-slate-200 bg-white p-4"><div className="flex items-start justify-between gap-3"><div><h4 className="font-medium text-slate-900">{source.title}</h4><p className="mt-2 text-sm leading-6 text-slate-600">{source.excerpt}</p></div><div className="flex flex-col items-end gap-2"><StatusPill tone="slate">{formatSourceKind(source.kind)}</StatusPill><span className="text-xs text-slate-400">{source.sourceFamily ?? source.domain}</span></div></div><div className="mt-3 flex flex-wrap gap-2 text-xs text-slate-500"><span>{source.availability}</span><span>match {source.entityConfidence}</span><span>{source.provenance.toLowerCase().replace(/_/g, ' ')}</span></div>{source.businessMatchReason?.length ? <p className="mt-2 text-xs text-slate-500">Matched by: {source.businessMatchReason.slice(0, 3).join(', ')}</p> : null}{source.notes?.length ? <p className="mt-2 text-xs text-amber-700">{source.notes[0]}</p> : null}{source.evidence.length ? <ul className="mt-3 space-y-2 text-sm text-slate-500">{source.evidence.slice(0, 2).map((item) => <li key={item}>{item}</li>)}</ul> : null}<a href={source.url} target="_blank" rel="noreferrer" className="mt-3 inline-flex text-sm font-medium text-sky-700">Open source</a></div>; }
function ModeBanner({ mode, compact = false }: { mode: ResearchMode; compact?: boolean }) { return <span className={`inline-flex items-center rounded-full border px-3 py-1 text-xs font-semibold ${mode === 'BUSINESS' ? 'border-emerald-200 bg-emerald-50 text-emerald-700' : 'border-violet-200 bg-violet-50 text-violet-700'} ${compact ? '' : 'self-start'}`}>{mode === 'BUSINESS' ? 'BUSINESS MODE, exact location' : 'CORPORATION MODE, company-wide'}</span>; }
function InlineNote({ children }: { children: ReactNode }) { return <div className="mb-4 rounded-[18px] border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">{children}</div>; }
function SearchField({ label, value, onChange, placeholder }: { label: string; value: string; onChange: (value: string) => void; placeholder: string }) { return <label className="block"><span className="mb-2 block text-sm font-medium text-slate-700">{label}</span><input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 outline-none placeholder:text-slate-400 focus:border-slate-300" /></label>; }
function LoadingPanel({ label }: { label: string }) { return <div className="rounded-[24px] border border-slate-200 bg-white p-5"><div className="flex items-center gap-3"><span className="inline-flex h-2.5 w-2.5 animate-pulse rounded-full bg-emerald-500" /><p className="font-medium text-slate-700">{label}</p></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full w-1/2 animate-pulse rounded-full bg-slate-900" /></div></div>; }
function ErrorMessage({ message }: { message: string }) { return <div className="rounded-[22px] border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{message}</div>; }
function EmptyState({ copy }: { copy: string }) { return <div className="rounded-[22px] border border-dashed border-slate-200 bg-slate-50 p-8 text-sm text-slate-500">{copy}</div>; }
function MiniStat({ label, value }: { label: string; value: string | number }) { return <div className="rounded-[18px] border border-slate-200 bg-white p-4"><p className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-400">{label}</p><p className="mt-2 text-lg font-semibold text-slate-950 break-words">{value}</p></div>; }
function MetricChip({ label }: { label: string }) { return <span className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-600">{label}</span>; }
function StatusPill({ children, tone }: { children: ReactNode; tone: 'slate' | 'green' | 'amber' | 'orange' }) { const tones = { slate: 'border-slate-200 bg-slate-100 text-slate-700', green: 'border-emerald-200 bg-emerald-50 text-emerald-700', amber: 'border-amber-200 bg-amber-50 text-amber-700', orange: 'border-orange-200 bg-orange-50 text-orange-700' } as const; return <span className={`rounded-full border px-3 py-1 text-xs font-semibold ${tones[tone]}`}>{children}</span>; }
function useRecentBusinesses() { const [ids, setIds] = useState<string[]>(() => readRecentBusinessIds()); const [businesses, setBusinesses] = useState<Business[]>([]); useEffect(() => { const sync = () => setIds(readRecentBusinessIds()); window.addEventListener('storage', sync); window.addEventListener('businessforge:recent-businesses', sync as EventListener); return () => { window.removeEventListener('storage', sync); window.removeEventListener('businessforge:recent-businesses', sync as EventListener); }; }, []); useEffect(() => { let cancelled = false; if (!ids.length) { setBusinesses([]); return; } Promise.all(ids.map((id) => api.getBusiness(id).catch(() => null))).then((items) => { if (cancelled) return; setBusinesses(items.filter(Boolean) as Business[]); }); return () => { cancelled = true; }; }, [ids]); return businesses; }
function readRecentBusinessIds() { if (typeof window === 'undefined') return []; try { const value = window.localStorage.getItem(recentBusinessKey); const parsed = value ? JSON.parse(value) : []; return Array.isArray(parsed) ? parsed.filter((item): item is string => typeof item === 'string') : []; } catch { return []; } }
function rememberBusiness(businessId: string) { if (typeof window === 'undefined') return; const next = [businessId, ...readRecentBusinessIds().filter((id) => id !== businessId)].slice(0, 8); window.localStorage.setItem(recentBusinessKey, JSON.stringify(next)); window.dispatchEvent(new Event('businessforge:recent-businesses')); }
function toDiscoveryParams(draft: SearchDraft) { const params = new URLSearchParams(); params.set('q', draft.query); params.set('mode', draft.mode); if (draft.websiteUrl.trim()) params.set('website', draft.websiteUrl.trim()); if (draft.locationText.trim()) params.set('location', draft.locationText.trim()); if (draft.coordinates) { params.set('lat', String(draft.coordinates.latitude)); params.set('lng', String(draft.coordinates.longitude)); } return params; }
function groupSources(sources: Source[]) { return Array.from(sources.reduce((map, source) => { const key = source.kind; const current = map.get(key) ?? { key, label: formatSourceKind(key), summary: '', items: [] as Source[] }; current.items.push(source); map.set(key, current); return map; }, new Map<string, { key: string; label: string; summary: string; items: Source[] }>()).values()).map((group) => ({ ...group, summary: summarizeGroup(group.items) })).sort((a, b) => b.items.length - a.items.length); }
function summarizeGroup(items: Source[]) { const families = Array.from(new Set(items.map((item) => item.sourceFamily).filter(Boolean))); const snippets = items.flatMap((item) => item.evidence).slice(0, 2); return [families.slice(0, 2).join(', '), snippets.join(' • ')].filter(Boolean).join(' • '); }
function uniqueSourcesFromEvidence(items: EvidenceItem[], sourcesById: Map<string, Source>) { const seen = new Set<string>(); const sources: Source[] = []; items.forEach((item) => item.sourceIds.forEach((sourceId) => { const source = sourcesById.get(sourceId); if (source && !seen.has(source.id)) { seen.add(source.id); sources.push(source); } })); return sources; }
function formatSourceKind(kind: string) { const labels: Record<string, string> = { website: 'Official', review: 'Reviews', directory: 'Directories', social: 'Social', news: 'News', search: 'Search', menu: 'Menu', operations: 'Operations', knowledge: 'Knowledge', forum: 'Forums' }; return labels[kind] ?? startCase(kind); }
function findingTone(sentiment: string): 'slate' | 'green' | 'amber' | 'orange' { if (sentiment === 'positive') return 'green'; if (sentiment === 'negative') return 'amber'; if (sentiment === 'mixed') return 'orange'; return 'slate'; }
function humanizeResearchStage(stage: string) { const map: Record<string, string> = { 'Resolving business identity': 'Confirming the business and its public footprint', 'Gathering official, review, forum, news, and directory evidence': 'Collecting evidence across source types', 'Filtering and matching entities': 'Rejecting weak or wrong-location matches', 'Aggregating findings': 'Organizing findings', 'Preparing build workspace': 'Preparing the build workspace', Complete: 'Investigation complete' }; return map[stage] ?? stage; }
function humanizeFindingType(type: string) { const map: Record<string, string> = { demand: 'Demand signal', friction: 'Friction', offer: 'Offer', operations: 'Operations', proof: 'Proof', audience: 'Audience' }; return map[type] ?? startCase(type); }
function humanizeEffort(effort: string) { const map: Record<string, string> = { low: 'Light', medium: 'Moderate', high: 'Substantial' }; return map[effort] ?? startCase(effort); }
function describeOpportunityBuild(opportunity: Opportunity, category: string) { if (opportunity.category === 'conversion') return category === 'restaurant' ? 'A multi-file local order or booking flow with evidence-backed offer copy.' : 'A guided customer path with evidence-backed messaging, proof, and a simpler next step.'; if (opportunity.category === 'acquisition') return 'A repeatable promotion system tied to visible public signals.'; return 'A cleaner handoff and follow-up system.'; }
function humanizePlanStatus(status: string) { const map: Record<string, string> = { todo: 'Not started', ready: 'Ready', doing: 'In progress', done: 'Complete' }; return map[status] ?? startCase(status); }
function humanizeTaskTitle(title: string) { return title.replace(/^Execute /, '').replace(/ workflow$/i, '').replace(/^Frame /, '').trim().replace(/-/g, ' '); }
function humanizeTaskStatus(status: string) { const map: Record<string, string> = { queued: 'Waiting', running: 'In progress', blocked: 'Needs review', done: 'Complete' }; return map[status] ?? startCase(status); }
function humanizeTaskNotes(notes: string) { return notes.replace('Marked complete from the workspace.', 'Marked complete from this workspace.').replace('Pulled into active execution.', 'Work has started on this step.').replace('Blocked manually from the workspace for operator review.', 'This step was paused for review.').replace('Evidence-linked thesis published.', 'The initial direction has been set.').replace('Waiting on upstream handoff.', 'Waiting for the earlier step to finish.').replace(/Working on /, 'Currently building ').replace(/Pulled into execution after .* reviewed operator input\./, 'Moved into active work after your instruction was reviewed.'); }
function humanizeRuntimeStatus(status: string) { const map: Record<string, string> = { executing: 'Building', stable: 'Running', ready: 'Ready', idle: 'Not started' }; return map[status] ?? startCase(status); }
function humanizeDeploymentState(state: string) { const map: Record<string, string> = { draft: 'Draft', validating: 'Checking', deploying: 'Preparing preview', live: 'Preview ready' }; return map[state] ?? startCase(state); }
function humanizeEventType(type: string) { const map: Record<string, string> = { 'task-update': 'Progress update', handoff: 'Handoff', interaction: 'Instruction received', 'capability-request': 'External coverage note', system: 'System update', 'build-event': 'Build event' }; return map[type] ?? startCase(type); }
function humanizeEventText(event: RuntimeEvent) { return event.text.replace('Research evidence normalized into structured findings.', 'Research findings were organized and prepared for review.').replace(/Selected opportunity mapped into .* agent roles for /, 'The selected plan was translated into a working build sequence for ').replace('Primary execution task is in progress.', 'The first major build step is underway.').replace(/ updated to done\./, ' was marked complete.').replace(/ updated to running\./, ' is now in progress.').replace(/ updated to blocked\./, ' was paused for review.').replace('Operator message routed to', 'Your instruction was sent to').replace('requested missing capability coverage for', 'flagged external coverage still needed for').replace('pulled', 'moved').replace('into active execution.', 'into active work.'); }
function toPlainError(message: string, fallback: string) { return message.startsWith('Request failed:') ? fallback : message; }
function formatTime(at: string) { return new Date(at).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }); }
function startCase(value: string) { return value.split(/[\s-]+/).filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' '); }
function formatDistance(meters: number) { return meters < 1000 ? `${meters}m away` : `${(meters / 1000).toFixed(1)}km away`; }
